import{_ as a,o as r,c as t,a5 as n}from"./chunks/framework.bIR-4glx.js";const g=JSON.parse('{"title":"Bibliography","description":"The studies, official guidance, and specifications actually cited in Still Here, grouped by subject and mapped to the chapter that uses each source.","frontmatter":{"title":"Bibliography","description":"The studies, official guidance, and specifications actually cited in Still Here, grouped by subject and mapped to the chapter that uses each source.","updated":"2026-11-23T00:00:00.000Z"},"headers":[],"relativePath":"en/reference/bibliography.md","filePath":"en/reference/bibliography.md","lastUpdated":1795392000000}'),i={name:"en/reference/bibliography.md"};function o(s,e,l,d,h,c){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="bibliography" tabindex="-1">Bibliography <a class="header-anchor" href="#bibliography" aria-label="Permalink to &quot;Bibliography&quot;">​</a></h1><p>This is a selective list of sources the book actually cites. It is not exhaustive. Papers and books are not distributed with the repository; readers reach them through their DOI or official link. Each entry names the chapter where it is used so the context and limits can be checked.</p><h2 id="how-to-use-this-list" tabindex="-1">How to Use This List <a class="header-anchor" href="#how-to-use-this-list" aria-label="Permalink to &quot;How to Use This List&quot;">​</a></h2><ul><li>A research finding describes results under its own sample, materials, measures, and conditions. It is not a personal guarantee.</li><li>Official guidance and specifications change. Record the version and access date when citing them.</li><li>When a link fails, the book keeps the original task and looks for the current page from the same source. It does not pile up new links just to keep a count.</li></ul><h2 id="learning-and-memory" tabindex="-1">Learning and Memory <a class="header-anchor" href="#learning-and-memory" aria-label="Permalink to &quot;Learning and Memory&quot;">​</a></h2><ul><li>Dunlosky, J., Rawson, K. A., Marsh, E. J., Nathan, M. J., &amp; Willingham, D. T. (2013). <em>Improving Students&#39; Learning With Effective Learning Techniques</em>. <a href="https://doi.org/10.1177/1529100612453266" target="_blank" rel="noreferrer">https://doi.org/10.1177/1529100612453266</a> — used in <a href="./../threads/part-1/1-understanding">Learning Principles</a>.</li><li>Roediger, H. L., &amp; Karpicke, J. D. (2006). <em>Test-Enhanced Learning</em>. <a href="https://doi.org/10.1111/j.1467-9280.2006.01693.x" target="_blank" rel="noreferrer">https://doi.org/10.1111/j.1467-9280.2006.01693.x</a> — used in <a href="./../threads/part-1/1-understanding">Learning Principles</a> and <a href="./../threads/part-1/2-vocabulary">Vocabulary</a>.</li><li>Cepeda, N. J., Pashler, H., Vul, E., Wixted, J. T., &amp; Rohrer, D. (2006). <em>Distributed Practice in Verbal Recall Tasks</em>. <a href="https://doi.org/10.1037/0033-2909.132.3.354" target="_blank" rel="noreferrer">https://doi.org/10.1037/0033-2909.132.3.354</a> — used in <a href="./../threads/part-1/1-understanding">Learning Principles</a>.</li><li>Hattie, J., &amp; Timperley, H. (2007). <em>The Power of Feedback</em>. <a href="https://doi.org/10.3102/003465430298487" target="_blank" rel="noreferrer">https://doi.org/10.3102/003465430298487</a> — used in <a href="./../threads/part-1/1-understanding">Learning Principles</a> and <a href="./../threads/part-1/6-writing">Writing</a>.</li><li>Rasch, B., &amp; Born, J. (2013). <em>About Sleep&#39;s Role in Memory</em>. <a href="https://doi.org/10.1152/physrev.00032.2012" target="_blank" rel="noreferrer">https://doi.org/10.1152/physrev.00032.2012</a> — used in <a href="./../threads/part-1/1-understanding">Learning Principles</a>.</li><li>Pashler, H., McDaniel, M., Rohrer, D., &amp; Bjork, R. (2008). <em>Learning Styles: Concepts and Evidence</em>. <a href="https://doi.org/10.1111/j.1539-6053.2009.01038.x" target="_blank" rel="noreferrer">https://doi.org/10.1111/j.1539-6053.2009.01038.x</a> — used in <a href="./../threads/part-1/1-understanding">Learning Principles</a> and <a href="./../threads/part-1/2-vocabulary">Vocabulary</a>.</li></ul><h2 id="vocabulary-and-language-assessment" tabindex="-1">Vocabulary and Language Assessment <a class="header-anchor" href="#vocabulary-and-language-assessment" aria-label="Permalink to &quot;Vocabulary and Language Assessment&quot;">​</a></h2><ul><li>Hu, M., &amp; Nation, I. S. P. (2000). <em>Vocabulary Density and Reading Comprehension</em>. <a href="https://doi.org/10.64152/10125/66973" target="_blank" rel="noreferrer">https://doi.org/10.64152/10125/66973</a> — used in <a href="./../threads/part-1/2-vocabulary">Vocabulary</a>.</li><li>Nation, I. S. P. (2006). <em>How Large a Vocabulary Is Needed for Reading and Listening?</em> <a href="https://doi.org/10.3138/cmlr.63.1.59" target="_blank" rel="noreferrer">https://doi.org/10.3138/cmlr.63.1.59</a> — used in <a href="./../threads/part-1/2-vocabulary">Vocabulary</a>.</li><li>Schmitt, N., Jiang, X., &amp; Grabe, W. (2011). <em>The Percentage of Words Known in a Text and Reading Comprehension</em>. <a href="https://doi.org/10.1111/j.1540-4781.2011.01146.x" target="_blank" rel="noreferrer">https://doi.org/10.1111/j.1540-4781.2011.01146.x</a> — used in <a href="./../threads/part-1/2-vocabulary">Vocabulary</a>.</li><li>Webb, S. (2008). <em>Receptive and Productive Vocabulary Sizes of L2 Learners</em>. <a href="https://doi.org/10.1017/S0272263108080042" target="_blank" rel="noreferrer">https://doi.org/10.1017/S0272263108080042</a> — used in <a href="./../threads/part-1/2-vocabulary">Vocabulary</a>.</li><li>Webb, S., Yanagisawa, A., &amp; Uchihara, T. (2020). <em>How Effective Are Intentional Vocabulary-Learning Activities?</em> <a href="https://doi.org/10.1111/modl.12671" target="_blank" rel="noreferrer">https://doi.org/10.1111/modl.12671</a> — used in <a href="./../threads/part-1/2-vocabulary">Vocabulary</a>.</li></ul><h2 id="listening-reading-speaking-and-writing" tabindex="-1">Listening, Reading, Speaking, and Writing <a class="header-anchor" href="#listening-reading-speaking-and-writing" aria-label="Permalink to &quot;Listening, Reading, Speaking, and Writing&quot;">​</a></h2><ul><li>Norris, J. M., &amp; Ortega, L. (2000). <em>Effectiveness of L2 Instruction</em>. <a href="https://doi.org/10.1111/0023-8333.00136" target="_blank" rel="noreferrer">https://doi.org/10.1111/0023-8333.00136</a> — used in <a href="./../threads/part-1/grammar">Grammar</a>.</li><li>Spada, N., &amp; Tomita, Y. (2010). <em>Interactions Between Type of Instruction and Type of Language Feature</em>. <a href="https://doi.org/10.1111/j.1467-9922.2010.00562.x" target="_blank" rel="noreferrer">https://doi.org/10.1111/j.1467-9922.2010.00562.x</a> — used in <a href="./../threads/part-1/grammar">Grammar</a>.</li><li>Vandergrift, L., &amp; Tafaghodtari, M. H. (2010). <em>Teaching L2 Learners How to Listen Does Make a Difference</em>. <a href="https://doi.org/10.1111/j.1467-9922.2009.00559.x" target="_blank" rel="noreferrer">https://doi.org/10.1111/j.1467-9922.2009.00559.x</a> — used in <a href="./../threads/part-1/3-listening">Listening</a>.</li><li>Chang, A. C.-S., &amp; Millett, S. (2016). <em>Developing L2 Listening Fluency through Extended Listening-focused Activities</em>. <a href="https://doi.org/10.1177/0033688216631175" target="_blank" rel="noreferrer">https://doi.org/10.1177/0033688216631175</a> — used in <a href="./../threads/part-1/3-listening">Listening</a>.</li><li>Tauroza, S., &amp; Luk, J. (1997). <em>Accent and Second Language Listening Comprehension</em>. <a href="https://doi.org/10.1177/003368829702800104" target="_blank" rel="noreferrer">https://doi.org/10.1177/003368829702800104</a> — used in <a href="./../threads/part-1/3-listening">Listening</a>.</li><li>Jeon, E. H., &amp; Yamashita, J. (2014). <em>L2 Reading Comprehension and Its Correlates</em>. <a href="https://doi.org/10.1111/lang.12034" target="_blank" rel="noreferrer">https://doi.org/10.1111/lang.12034</a> — used in <a href="./../threads/part-1/4-reading">Reading</a>.</li><li>Jeon, E. H. (2022). <em>L2 Reading Comprehension and Its Correlates: An Updated Meta-analysis</em>. <a href="https://doi.org/10.1075/bpa.13.03jeo" target="_blank" rel="noreferrer">https://doi.org/10.1075/bpa.13.03jeo</a> — used in <a href="./../threads/part-1/4-reading">Reading</a>.</li><li>Akkakoson, S. (2013). <em>The Relationship between Strategic Reading Instruction and L2 Reading Achievement</em>. <a href="https://doi.org/10.1111/jrir.12004" target="_blank" rel="noreferrer">https://doi.org/10.1111/jrir.12004</a> — used in <a href="./../threads/part-1/4-reading">Reading</a>.</li><li>Derwing, T. M., &amp; Munro, M. J. (2005). <em>Second Language Accent and Pronunciation Teaching</em>. <a href="https://doi.org/10.2307/3588486" target="_blank" rel="noreferrer">https://doi.org/10.2307/3588486</a> — used in <a href="./../threads/part-1/5-speaking">Speaking</a>.</li><li>Levis, J. M. (2005). <em>Changing Contexts and Shifting Paradigms in Pronunciation Teaching</em>. <a href="https://doi.org/10.2307/3588485" target="_blank" rel="noreferrer">https://doi.org/10.2307/3588485</a> — used in <a href="./../threads/part-1/5-speaking">Speaking</a>.</li><li>Saito, K. (2012). <em>Effects of Instruction on L2 Pronunciation Development</em>. <a href="https://doi.org/10.1002/tesq.67" target="_blank" rel="noreferrer">https://doi.org/10.1002/tesq.67</a> — used in <a href="./../threads/part-1/5-speaking">Speaking</a>.</li><li>Kang, E., &amp; Han, Z. (2015). <em>The Efficacy of Written Corrective Feedback in Improving L2 Written Accuracy</em>. <a href="https://doi.org/10.1111/modl.12189" target="_blank" rel="noreferrer">https://doi.org/10.1111/modl.12189</a> — used in <a href="./../threads/part-1/6-writing">Writing</a>.</li><li>Vuogan, A., &amp; Li, S. (2022). <em>Examining the Effectiveness of Peer Feedback in Second Language Writing</em>. <a href="https://doi.org/10.1002/tesq.3178" target="_blank" rel="noreferrer">https://doi.org/10.1002/tesq.3178</a> — used in <a href="./../threads/part-1/6-writing">Writing</a>.</li><li>Zhai, N., &amp; Ma, X. (2022). <em>The Effectiveness of Automated Writing Evaluation on Writing Quality</em>. <a href="https://doi.org/10.1177/07356331221127300" target="_blank" rel="noreferrer">https://doi.org/10.1177/07356331221127300</a> — used in <a href="./../threads/part-1/6-writing">Writing</a>.</li></ul><h2 id="language-and-ability-frameworks" tabindex="-1">Language and Ability Frameworks <a class="header-anchor" href="#language-and-ability-frameworks" aria-label="Permalink to &quot;Language and Ability Frameworks&quot;">​</a></h2><ul><li>Council of Europe. <em>CEFR 3.3 Global Scale</em>. <a href="https://www.coe.int/en/web/common-european-framework-reference-languages/table-1-cefr-3.3-common-reference-levels-global-scale" target="_blank" rel="noreferrer">https://www.coe.int/en/web/common-european-framework-reference-languages/table-1-cefr-3.3-common-reference-levels-global-scale</a> — used in <a href="./../threads/part-1/0-cefr">CEFR Goals and Self-check</a> and <a href="./../threads/part-1/8-job-search-english">Job-search English</a>. The book treats levels as task coordinates, not hiring lines. The table is a working summary, not an official translation.</li></ul><h2 id="mental-health-and-recovery" tabindex="-1">Mental Health and Recovery <a class="header-anchor" href="#mental-health-and-recovery" aria-label="Permalink to &quot;Mental Health and Recovery&quot;">​</a></h2><ul><li>World Health Organization. <em>Suicide fact sheet</em>. <a href="https://www.who.int/news-room/fact-sheets/detail/suicide" target="_blank" rel="noreferrer">https://www.who.int/news-room/fact-sheets/detail/suicide</a> — used in <a href="./../threads/part-2/recovery">Recovery</a>. Used only for the public-health direction on access to means, identification, assessment, management, and follow-up. It does not supply a diagnosis, hotline, or individual treatment plan.</li><li>World Health Organization. <em>Mental health at work</em>. <a href="https://www.who.int/news-room/fact-sheets/detail/mental-health-at-work" target="_blank" rel="noreferrer">https://www.who.int/news-room/fact-sheets/detail/mental-health-at-work</a> — used in <a href="./../threads/part-2/recovery">Recovery</a>.</li><li>World Health Organization. <em>Guidelines on mental health at work</em>. <a href="https://www.who.int/publications/i/item/9789240053052" target="_blank" rel="noreferrer">https://www.who.int/publications/i/item/9789240053052</a> — used in <a href="./../threads/part-2/recovery">Recovery</a>. Used for reasonable accommodation, phased return, and workplace support; concrete arrangements remain with the person, professionals, the employer, and applicable rules.</li></ul><h2 id="ai-protocols-and-vendor-documentation" tabindex="-1">AI, Protocols, and Vendor Documentation <a class="header-anchor" href="#ai-protocols-and-vendor-documentation" aria-label="Permalink to &quot;AI, Protocols, and Vendor Documentation&quot;">​</a></h2><ul><li>Anthropic. <em>Building effective agents</em>. <a href="https://www.anthropic.com/engineering/building-effective-agents" target="_blank" rel="noreferrer">https://www.anthropic.com/engineering/building-effective-agents</a> — used in <a href="./../threads/part-3/6-ai-trends-and-learning-roadmap">AI Trends and a Learning Roadmap</a> and the AI workflow practice page.</li><li>Anthropic. <em>Effective context engineering for AI agents</em>. <a href="https://www.anthropic.com/engineering/effective-context-engineering-for-ai-agents" target="_blank" rel="noreferrer">https://www.anthropic.com/engineering/effective-context-engineering-for-ai-agents</a> — used in <a href="./../threads/part-3/6-ai-trends-and-learning-roadmap">AI Trends and a Learning Roadmap</a>.</li><li>Anthropic. <em>Demystifying evals for AI agents</em>. <a href="https://www.anthropic.com/engineering/demystifying-evals-for-ai-agents" target="_blank" rel="noreferrer">https://www.anthropic.com/engineering/demystifying-evals-for-ai-agents</a> — used in <a href="./../threads/part-3/6-ai-trends-and-learning-roadmap">AI Trends and a Learning Roadmap</a> and the AI evaluation practice page.</li><li>Anthropic. <em>Measuring AI agent autonomy in practice</em>. <a href="https://www.anthropic.com/research/measuring-agent-autonomy" target="_blank" rel="noreferrer">https://www.anthropic.com/research/measuring-agent-autonomy</a> — used in <a href="./../threads/part-3/6-ai-trends-and-learning-roadmap">AI Trends and a Learning Roadmap</a>. The data come from the vendor&#39;s own usage sample, not a universal benchmark.</li><li>Anthropic. <em>An update on independent evaluators</em>. <a href="https://www.anthropic.com/news/an-update-on-independent-evaluators" target="_blank" rel="noreferrer">https://www.anthropic.com/news/an-update-on-independent-evaluators</a> — used in <a href="./../threads/part-3/6-ai-trends-and-learning-roadmap">AI Trends and a Learning Roadmap</a>. A vendor note, not an industry standard.</li><li>Anthropic. <em>2026 Usage Policy update</em>. <a href="https://www.anthropic.com/news/2026-usage-policy-update" target="_blank" rel="noreferrer">https://www.anthropic.com/news/2026-usage-policy-update</a> — used in <a href="./../threads/part-3/6-ai-trends-and-learning-roadmap">AI Trends and a Learning Roadmap</a>. Used to record policy version, effective date, and high-risk review; not legal advice.</li><li>Model Context Protocol. <em>Specification, 2026-07-28</em>. <a href="https://modelcontextprotocol.io/specification/2026-07-28" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/specification/2026-07-28</a> — used in <a href="./../threads/part-3/6-ai-trends-and-learning-roadmap">AI Trends and a Learning Roadmap</a>, <a href="./../threads/part-3/2-ai-development-and-resource-layer">AI Learning, Project Development, and Resource-layer Entrepreneurship</a>, and <a href="./../threads/practice/resource-layer-business">The Resource Layer and Enterprise Services</a>. Interoperability boundaries for resources, prompts, tools, and optional Tasks; the protocol does not perform an implementation&#39;s security review.</li><li>Model Context Protocol. <em>Security Best Practices, 2026-07-28</em>. <a href="https://modelcontextprotocol.io/docs/2026-07-28/tutorials/security/security_best_practices" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/docs/2026-07-28/tutorials/security/security_best_practices</a> — used in <a href="./../threads/part-3/6-ai-trends-and-learning-roadmap">AI Trends and a Learning Roadmap</a>. Least privilege, token passthrough, SSRF, redirects, and consent boundaries.</li><li>Google. <em>Image understanding</em>. <a href="https://ai.google.dev/gemini-api/docs/image-understanding" target="_blank" rel="noreferrer">https://ai.google.dev/gemini-api/docs/image-understanding</a> — used in <a href="./../threads/part-3/6-ai-trends-and-learning-roadmap">AI Trends and a Learning Roadmap</a>.</li><li>Google. <em>Gemma overview</em>. <a href="https://ai.google.dev/gemma/docs/core" target="_blank" rel="noreferrer">https://ai.google.dev/gemma/docs/core</a> and <em>Ollama integration</em>. <a href="https://ai.google.dev/gemma/docs/integrations/ollama" target="_blank" rel="noreferrer">https://ai.google.dev/gemma/docs/integrations/ollama</a> — used in <a href="./../threads/part-3/6-ai-trends-and-learning-roadmap">AI Trends and a Learning Roadmap</a>. Examples of open weights, local execution, and resource trade-offs.</li><li>C2PA. <em>2.2 Explainer</em>. <a href="https://c2pa.org/specifications/specifications/2.2/explainer/Explainer.html" target="_blank" rel="noreferrer">https://c2pa.org/specifications/specifications/2.2/explainer/Explainer.html</a> — used in <a href="./../threads/part-3/6-ai-trends-and-learning-roadmap">AI Trends and a Learning Roadmap</a>. A provenance credential does not by itself prove that content is true.</li><li>UNESCO. <em>AI competency framework for students</em>. <a href="https://www.unesco.org/en/articles/ai-competency-framework-students" target="_blank" rel="noreferrer">https://www.unesco.org/en/articles/ai-competency-framework-students</a> — used in <a href="./../threads/part-3/6-ai-trends-and-learning-roadmap">AI Trends and a Learning Roadmap</a>.</li><li>UNESCO. <em>Guidance for generative AI in education and research</em>. <a href="https://www.unesco.org/en/articles/guidance-generative-ai-education-and-research" target="_blank" rel="noreferrer">https://www.unesco.org/en/articles/guidance-generative-ai-education-and-research</a> — used in <a href="./../threads/part-4/family-learning">Family Learning</a>. Used only for the human-centred capability framing; local school policy, platform terms, and professional judgment remain separately required.</li><li>IBM. <em>RAG vs. Fine-tuning</em>. <a href="https://www.ibm.com/think/topics/rag-vs-fine-tuning" target="_blank" rel="noreferrer">https://www.ibm.com/think/topics/rag-vs-fine-tuning</a> — used in <a href="./../threads/part-3/1-ai-learning">Learning Anything with AI</a>.</li><li>OpenAI. <em>Study Mode</em> and <em>Projects in ChatGPT</em>. <a href="https://openai.com/zh-Hans-CN/index/chatgpt-study-mode/" target="_blank" rel="noreferrer">https://openai.com/zh-Hans-CN/index/chatgpt-study-mode/</a> and <a href="https://help.openai.com/en/articles/10169521-projects" target="_blank" rel="noreferrer">https://help.openai.com/en/articles/10169521-projects</a> — used in <a href="./../threads/part-1/7-ai">Learning English with AI</a>. Product entry points change by region, account, and plan.</li><li>Google. <em>Learning tools in Gemini</em>. <a href="https://support.google.com/gemini/answer/16448384" target="_blank" rel="noreferrer">https://support.google.com/gemini/answer/16448384</a> — used in <a href="./../threads/part-1/7-ai">Learning English with AI</a>.</li><li>Anthropic. <em>What are projects?</em> <a href="https://support.claude.com/en/articles/9517075-what-are-projects" target="_blank" rel="noreferrer">https://support.claude.com/en/articles/9517075-what-are-projects</a> — used in <a href="./../threads/part-1/7-ai">Learning English with AI</a>. Free accounts can create up to five projects; enhanced knowledge retrieval requires a paid plan.</li></ul><h2 id="literature-and-quotations" tabindex="-1">Literature and Quotations <a class="header-anchor" href="#literature-and-quotations" aria-label="Permalink to &quot;Literature and Quotations&quot;">​</a></h2><ul><li>Gu Cheng. A short line quoted in <a href="./../threads/part-2/my-story">My Story</a>. The book quotes one short line with attribution, does not reproduce the poem, and claims no rights in it.</li><li>Marshall B. Rosenberg, <em>Nonviolent Communication</em>. <a href="./../threads/part-2/communication">Communication</a> draws on the observation–feeling–need–request frame and offers an original adaptation, without reproducing the text.</li></ul><h2 id="maintenance" tabindex="-1">Maintenance <a class="header-anchor" href="#maintenance" aria-label="Permalink to &quot;Maintenance&quot;">​</a></h2><p>When adding a source, update <code>ATTRIBUTIONS.md</code> and this chapter together. Record the author, year, title, DOI or official link, verification date, and the chapter that uses it. Material whose rights cannot be confirmed, or which can no longer be verified, does not enter this list.</p>',20)])])}const m=a(i,[["render",o]]);export{g as __pageData,m as default};
